strings:
:root { color-scheme: light; }
* { box-sizing: border-box; }
body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  color: #0b1021;
  background: #ffffff;
}
header {
  display: flex;
  align-items: center;
  gap: 24px;
  padding: 16px 24px;
  background: #0b1021;
  color: #c7d2fe;
}
header a { color: #c7d2fe; font-size: 14px; text-decoration: none; }
.cta {
  margin-left: auto;
  background: #3b5bdb;
  color: #ffffff;
  border-radius: 7px;
  padding: 13px 18px;
  font-size: 15px;
  text-decoration: none;
}
main { padding: 24px; }
h1 { font-size: 32px; line-height: 40px; margin: 0 0 16px; }
.cards { display: flex; gap: 16px; margin-bottom: 24px; }
.card {
  background: #f6f7fb;
  border-radius: 8px;
  padding: 16px;
  width: 220px;
}
.card a { color: #1b6ef3; font-size: 14px; }
table { border-collapse: collapse; width: 100%; font-size: 13px; margin-bottom: 24px; }
th, td { text-align: left; padding: 8px 12px; border-bottom: 1px solid #e6e8f0; }
form { display: grid; gap: 12px; max-width: 420px; }
label { font-size: 13px; }
input {
  background: #ffffff;
  border: 1px solid #d6d9e6;
  border-radius: 6px;
  padding: 12px;
  font-size: 15px;
  width: 100%;
}
button[type="submit"] {
  background: #1b6ef3;
  color: #ffffff;
  border: 0;
  border-radius: 6px;
  padding: 16px;
  font-size: 15px;
}
/* A list item outside a list: the DOM implicit role and the accessibility
   tree genuinely disagree here, which is what a retained conflict is for. */
li.loose { list-style: none; padding: 8px 0; font-size: 14px; }
iframe { width: 100%; height: 120px; border: 1px solid #e6e8f0; border-radius: 8px; }
footer { padding: 24px; color: #6b7280; font-size: 13px; }
